def generate_safe_fn(fn, custom_gradient, bounds):
    """
    Generate a safe version of the input function by limiting its input range.

    Args:
    fn: The input function to be made safe.
    custom_gradient: A custom gradient function for backpropagation.
    bounds: A tuple defining the safe input range for the function.

    Returns:
    A safe version of the input function.
    """
    def safe_fn(x):
        if bounds[0] <= x <= bounds[1]:
            return fn(x)
        else:
            if x < bounds[0]:
                return fn(bounds[0])
            else:
                return fn(bounds[1])

    def safe_fn_grad(x, _, x_dot):
        if bounds[0] <= x <= bounds[1]:
            return custom_gradient(x, _, x_dot)
        else:
            if x < bounds[0]:
                return custom_gradient(bounds[0], _, x_dot)
            else:
                return custom_gradient(bounds[1], _, x_dot)

    return safe_fn, safe_fn_grad

def safe_exp(x):
    """
    The function creates a safe exponential function that avoids overflow issues by limiting the input range.
    It uses a helper function to generate this safe version of the exponential function, applying a custom gradient function for backpropagation in automatic differentiation contexts.

    Input-Output Arguments
    :param x: The input value for which the safe exponential function is computed.
    :return: The result of applying the safe exponential function to the input x.
    """
    max_val = 1e100
    min_val = -np.log(max_val)
    return generate_safe_fn(jnp.exp, lambda x, _, x_dot: jnp.exp(x) * x_dot, (min_val, np.nextafter(np.log(max_val), np.float32(0))))(x)
